package stream

import (
	"os"
	"path/filepath"
	"testing"
)

// seedItemTree lays out one item's artifact root exactly as the lane leaves
// it mid-repack: the keepNonce build (with a segment file inside), two
// superseded build directories, both staging shapes the pack lane uses
// (.tmp-<nonce> head staging and .tmp-tail-<nonce> tail staging) with
// in-flight content, a stray non-directory entry, and another item's build
// tree.
func seedItemTree(t *testing.T, root string) {
	t.Helper()
	write := func(rel string) string {
		path := filepath.Join(root, rel)
		if err := os.MkdirAll(path, 0o755); err != nil {
			t.Fatalf("mkdir %s: %v", rel, err)
		}
		return path
	}
	touch := func(rel string) {
		if err := os.WriteFile(filepath.Join(root, rel), []byte("x"), 0o644); err != nil {
			t.Fatalf("write %s: %v", rel, err)
		}
	}
	write(filepath.Join("item", "keep0001"))
	touch(filepath.Join("item", "keep0001", "index.m3u8"))
	write(filepath.Join("item", "oldaaa1"))
	write(filepath.Join("item", "oldbbb2"))
	write(filepath.Join("item", ".tmp-ccc3", "t"))
	touch(filepath.Join("item", ".tmp-ccc3", "t", "seg.m4s"))
	write(filepath.Join("item", ".tmp-tail-ccc3"))
	write(filepath.Join("other", "dddddd1"))
	touch(filepath.Join("item", "stray.txt"))
}

// TestEvictSuperseded is the acceptance test for publish-replacement eviction
// (playback-capability-gate D5): every superseded build directory under the
// item's artifact root is removed while keepNonce, the in-flight `.tmp-*`
// staging directories, the stray file, and other items' trees all survive; a
// removal failure is best-effort (WARN, sweep continues, the landed pack never
// fails); unsafe path components refuse before anything is read.
func TestEvictSuperseded(t *testing.T) {
	t.Run("removes_superseded_keeps_keep_staging_other_items", func(t *testing.T) {
		root := t.TempDir()
		seedItemTree(t, root)

		(&Service{Root: root}).EvictSuperseded("item", "keep0001")

		for _, want := range []string{
			filepath.Join("item", "keep0001", "index.m3u8"),    // keepNonce survives, content intact
			filepath.Join("item", ".tmp-ccc3", "t", "seg.m4s"), // in-flight head staging survives
			filepath.Join("item", ".tmp-tail-ccc3"),            // in-flight tail staging survives
			filepath.Join("item", "stray.txt"),                 // non-directories never touched
			filepath.Join("other", "dddddd1"),                  // other items never touched
		} {
			if _, err := os.Stat(filepath.Join(root, want)); err != nil {
				t.Fatalf("%s must survive eviction: %v", want, err)
			}
		}
		for _, gone := range []string{
			filepath.Join("item", "oldaaa1"),
			filepath.Join("item", "oldbbb2"),
		} {
			if _, err := os.Stat(filepath.Join(root, gone)); !os.IsNotExist(err) {
				t.Fatalf("%s must be evicted, stat err = %v", gone, err)
			}
		}
	})

	t.Run("removal_failure_is_best_effort", func(t *testing.T) {
		root := t.TempDir()
		seedItemTree(t, root)
		locked := filepath.Join(root, "item", "oldaaa1")
		// A file inside the locked directory: unlinking it needs write
		// permission on the directory itself, so RemoveAll fails (an empty
		// directory would still fall to its parent's rmdir permission).
		if err := os.WriteFile(filepath.Join(locked, "seg.m4s"), []byte("x"), 0o644); err != nil {
			t.Fatalf("seed locked child: %v", err)
		}
		if err := os.Chmod(locked, 0o500); err != nil {
			t.Fatalf("chmod: %v", err)
		}
		t.Cleanup(func() { _ = os.Chmod(locked, 0o755) })

		(&Service{Root: root}).EvictSuperseded("item", "keep0001") // must not fail the landed pack

		if _, err := os.Stat(locked); err != nil {
			t.Fatalf("the failed removal's directory must remain for the next attempt: %v", err)
		}
		if _, err := os.Stat(filepath.Join(root, "item", "oldbbb2")); !os.IsNotExist(err) {
			t.Fatalf("the sweep must continue past the failed removal: oldbbb2 stat err = %v", err)
		}
		if _, err := os.Stat(filepath.Join(root, "item", "keep0001", "index.m3u8")); err != nil {
			t.Fatalf("keepNonce always survives: %v", err)
		}
	})

	t.Run("missing_item_directory_is_quiet", func(t *testing.T) {
		root := t.TempDir()
		(&Service{Root: root}).EvictSuperseded("never-published", "keep0001") // no panic, no error
	})

	t.Run("unsafe_components_refuse_without_reading", func(t *testing.T) {
		root := t.TempDir()
		seedItemTree(t, root)

		(&Service{Root: root}).EvictSuperseded("..", "keep0001")
		(&Service{Root: root}).EvictSuperseded("item", "..")

		// Nothing anywhere was touched — the traversal refusal precedes any read.
		if _, err := os.Stat(filepath.Join(root, "item", "oldaaa1")); err != nil {
			t.Fatalf("refusal must be a no-op: %v", err)
		}
	})
}
